# Import of required libraries
import re
import skyramp
import os
import time

from SkyrampUtils import (
    build_headers,
    create_deployment,
    create_flow,
    create_flow_run,
    create_work_pool,
    get_work_pool_stats,
    set_flow_run_state,
)


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:4200")

UUID_RE = r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    headers = build_headers()

    pool_a_name = skyramp.unique_suffix("sk-iso-pool-a")
    pool_b_name = skyramp.unique_suffix("sk-iso-pool-b")
    flow_name = skyramp.unique_suffix("sk-iso-flow")

    endpoint_3_POST_response = create_work_pool(
        client, headers, pool_a_name, concurrency_limit=None
    )

    assert skyramp.get_response_value(endpoint_3_POST_response, "name") == pool_a_name
    assert skyramp.get_response_value(endpoint_3_POST_response, "type") == "process"
    assert skyramp.get_response_value(endpoint_3_POST_response, "is_paused") is False
    assert skyramp.get_response_value(endpoint_3_POST_response, "status") == "NOT_READY"
    assert re.match(
        UUID_RE, str(skyramp.get_response_value(endpoint_3_POST_response, "id")), re.I
    )
    assert skyramp.check_schema(
        endpoint_3_POST_response, r'''{"concurrency_limit": null, "active_slots": null}'''
    )

    pool_a_id = skyramp.get_response_value(endpoint_3_POST_response, "id")

    endpoint_3_POST_1_response = create_work_pool(
        client, headers, pool_b_name, concurrency_limit=None
    )

    assert skyramp.get_response_value(endpoint_3_POST_1_response, "name") == pool_b_name
    assert skyramp.get_response_value(endpoint_3_POST_1_response, "type") == "process"
    assert (
        skyramp.get_response_value(endpoint_3_POST_1_response, "status") == "NOT_READY"
    )
    assert re.match(
        UUID_RE, str(skyramp.get_response_value(endpoint_3_POST_1_response, "id")), re.I
    )

    pool_b_id = skyramp.get_response_value(endpoint_3_POST_1_response, "id")

    assert pool_b_id != pool_a_id

    endpoint_2_POST_response = create_flow(client, headers, flow_name)

    assert skyramp.get_response_value(endpoint_2_POST_response, "name") == flow_name
    assert re.match(
        UUID_RE, str(skyramp.get_response_value(endpoint_2_POST_response, "id")), re.I
    )

    flow_id = skyramp.get_response_value(endpoint_2_POST_response, "id")

    endpoint_1_POST_response = create_deployment(
        client,
        headers,
        "sk-iso-deployment",
        flow_id,
        pool_a_name,
    )

    assert (
        skyramp.get_response_value(endpoint_1_POST_response, "name")
        == "sk-iso-deployment"
    )
    assert skyramp.get_response_value(endpoint_1_POST_response, "flow_id") == flow_id
    assert (
        skyramp.get_response_value(endpoint_1_POST_response, "work_pool_name")
        == pool_a_name
    )
    assert (
        skyramp.get_response_value(endpoint_1_POST_response, "work_queue_name")
        == "default"
    )
    assert re.match(
        UUID_RE, str(skyramp.get_response_value(endpoint_1_POST_response, "id")), re.I
    )

    deployment_id = skyramp.get_response_value(endpoint_1_POST_response, "id")

    create_flow_run_POST_response = create_flow_run(
        client,
        headers,
        deployment_id,
    )

    assert (
        skyramp.get_response_value(create_flow_run_POST_response, "deployment_id")
        == deployment_id
    )
    assert (
        skyramp.get_response_value(create_flow_run_POST_response, "flow_id") == flow_id
    )
    assert (
        skyramp.get_response_value(create_flow_run_POST_response, "work_pool_name")
        == pool_a_name
    )
    assert (
        skyramp.get_response_value(create_flow_run_POST_response, "work_queue_name")
        == "default"
    )
    assert (
        skyramp.get_response_value(create_flow_run_POST_response, "state.type")
        == "SCHEDULED"
    )
    assert re.match(
        UUID_RE,
        str(skyramp.get_response_value(create_flow_run_POST_response, "work_queue_id")),
        re.I,
    )

    set_state_POST_response = set_flow_run_state(
        client,
        headers,
        skyramp.get_response_value(create_flow_run_POST_response, "id"),
    )

    assert skyramp.get_response_value(set_state_POST_response, "status") == "ACCEPT"
    assert (
        skyramp.get_response_value(set_state_POST_response, "state.type") == "RUNNING"
    )

    stats_GET_response = get_work_pool_stats(
        client,
        headers,
        pool_a_id,
    )

    assert skyramp.get_response_value(stats_GET_response, "running") == 1
    assert skyramp.get_response_value(stats_GET_response, "pending") == 0
    assert skyramp.get_response_value(stats_GET_response, "completed_last_24h") == 0

    stats_GET_1_response = get_work_pool_stats(
        client,
        headers,
        pool_b_id,
    )

    assert skyramp.get_response_value(stats_GET_1_response, "running") == 0
    assert skyramp.get_response_value(stats_GET_1_response, "pending") == 0
    assert skyramp.get_response_value(stats_GET_1_response, "completed_last_24h") == 0
    assert (
        skyramp.get_response_value(stats_GET_response, "running")
        == skyramp.get_response_value(stats_GET_1_response, "running") + 1
    )


if __name__ == "__main__":
    test_integration()
